import collections
import six
import time

from threading import Thread
from six.moves.queue import Queue, Empty

from .model import QueryModel
from ..exception import InfoModelQueryParallelExecutionException, InfoModelQueryTimeoutException


class QueryExecutor(object):

    def __init__(self, im_provider, allow_negative_result=False):
        self.model = QueryModel(im_provider, allow_negative_result)

    def execute(self, query, timeout):
        """Execute query."""
        return self.model.query_infomodel(query, timeout)

    def execute_parallel_pass_if_all(self, queries, timeout):
        """Execute queries in parallel and pass if all passed."""
        queue = Queue()
        threads = [Thread(target=self._execute_in_thread, args=(query, queue, timeout)) for query in six.itervalues(queries)]

        for thread in threads:
            thread.start()

        for thread in threads:
            thread.join(timeout + 2)

        if queue.unfinished_tasks != len(queries):
            msg = '{} queries executed in parallel but {} threads finished.'
            raise InfoModelQueryParallelExecutionException(msg.format(len(queries), queue.unfinished_tasks))

        return self._collect_results(queue)

    def execute_parallel_pass_if_any(self, queries, timeout):
        """Execute queries in parallel and pass if any passed."""
        queue = Queue()
        threads = [Thread(target=self._execute_in_thread, args=(query, queue, timeout)) for query in six.itervalues(queries)]

        for thread in threads:
            thread.start()

        time_left = timeout + 2
        end = time.time() + time_left
        queries_finished = 0
        while queries_finished < len(queries) and time_left > 0:
            try:
                r = queue.get(timeout=time_left)
            except Empty:
                msg = '{} queries executed in parallel but {} threads finished in timeout={}'
                raise InfoModelQueryParallelExecutionException(msg.format(len(queries), queries_finished, timeout))
            queries_finished += 1
            if not isinstance(r, Exception):
                return r
            time_left = end - time.time()

        msg = 'None of parallel queries: "{}" pass in timeout={}.'
        raise InfoModelQueryTimeoutException(msg.format('", "'.join(six.itervalues(queries)), timeout))

    def _execute_in_thread(self, query, queue, timeout):
        try:
            queue.put(self.execute(query, timeout))
        except Exception as e:
            queue.put(e)

    def execute_sequence(self, queries, timeout):
        """Execute queries sequence on executor."""
        queries = collections.OrderedDict(sorted(six.iteritems(queries)))
        return [self.execute(query, float(timeout) / len(queries)) for _, query in six.iteritems(queries)]

    def execute_parallel_sequences(self, sequences, timeout):
        """Execute sequences in parallel."""
        queue = Queue()
        threads = []
        for sequence in six.itervalues(sequences):
            sequence = collections.OrderedDict(sorted(sequence.items()))
            thread = Thread(target=self._execute_sequence_in_thread, args=(sequence, queue, float(timeout) / len(sequence)))
            threads.append(thread)

        for thread in threads:
            thread.start()

        for thread in threads:
            thread.join(timeout + 2)

        num_queries = sum(len(seq) for seq in sequences.values())
        if queue.unfinished_tasks != num_queries:
            msg = '{} queries executed in parallel sequences but {} threads finished.'
            raise InfoModelQueryParallelExecutionException(msg.format(num_queries, queue.unfinished_tasks))

        return self._collect_results(queue)

    def _execute_sequence_in_thread(self, queries, queue, timeout):
        for query in six.itervalues(queries):
            self._execute_in_thread(query, queue, timeout)

    def _collect_results(self, queue):
        results = []
        while not queue.empty():
            r = queue.get()
            if isinstance(r, Exception):
                raise r
            results.append(r)
        return results
